// ============================================================
// Extract and validate approval payload
// ============================================================
const body = $input.first().json.body || $input.first().json;
const project_id = (body.project_id || '').trim();
const action = (body.action || '').trim().toLowerCase();
const concept_ids = body.concept_ids || [];
const notes = (body.notes || '').trim();

if (!project_id) throw new Error('project_id is required');
if (!['pm_approve', 'pm_reject', 'client_approve', 'client_reject'].includes(action)) {
  throw new Error('action must be one of: pm_approve, pm_reject, client_approve, client_reject');
}

return [{ json: { project_id, action, concept_ids, notes } }];

// ============================================================
// Merge project + concepts + payload into single context
// ============================================================
const payload = $('Extract Approval Payload').first().json;
const project = $('Fetch Project from Airtable').first().json;
const concepts = $input.all().map(item => item.json);

return [{ json: {
  ...payload,
  project,
  concepts,
  concept_count: concepts.length
} }];

// ============================================================
// PM Approve: Determine which concepts are approved vs rejected
// If concept_ids is empty, approve ALL concepts
// ============================================================
const data = $input.first().json;
const concept_ids = data.concept_ids || [];
const notes = data.notes;
const concepts = data.concepts;

const approvedConcepts = concept_ids.length > 0
  ? concepts.filter(c => concept_ids.includes(c.id))
  : concepts;
const rejectedConcepts = concept_ids.length > 0
  ? concepts.filter(c => !concept_ids.includes(c.id))
  : [];

const items = [];

// Approved concepts
for (const c of approvedConcepts) {
  items.push({ json: {
    record_id: c.id,
    pm_status: 'Approved',
    pm_notes: notes,
    overall_status: 'Client Review',
    _action: 'update_concept'
  }});
}

// Rejected concepts
for (const c of rejectedConcepts) {
  items.push({ json: {
    record_id: c.id,
    pm_status: 'Rejected',
    pm_notes: notes || 'Not selected by PM',
    overall_status: 'PM Review',
    _action: 'update_concept'
  }});
}

return items;

// ============================================================
// Build Slack notification for client concept review
// ============================================================
const data = $('Merge Context').first().json;
const project = data.project;
const concepts = data.concepts.filter(c => {
  const ids = data.concept_ids || [];
  return ids.length === 0 || ids.includes(c.id);
});

const conceptSummary = concepts.map((c, i) =>
  `${i + 1}. *${c.concept_name || c.fields?.concept_name || 'Concept'}*\n   _"${c.hook_text || c.fields?.hook_text || ''}"_\n   ${c.concept_pitch || c.fields?.concept_pitch || ''}`
).join('\n\n');

const brandName = project.brand_name || project.fields?.brand_name || 'Client';
const clientEmail = project.client_email || project.fields?.client_email || '';
const clientName = project.client_name || project.fields?.client_name || 'Client';
const projectId = data.project_id;

const slackBlocks = [
  {
    "type": "header",
    "text": { "type": "plain_text", "text": `Client Review: ${brandName} Concepts` }
  },
  {
    "type": "section",
    "text": {
      "type": "mrkdwn",
      "text": `PM has approved *${concepts.length} concepts* for ${brandName}.\nClient: ${clientName} (${clientEmail})\n\n*Approved Concepts:*\n\n${conceptSummary}\n\nConcepts are ready for client review. Share the Airtable view link with the client.`
    }
  },
  {
    "type": "actions",
    "elements": [
      {
        "type": "button",
        "text": { "type": "plain_text", "text": "Client Airtable View" },
        "url": `https://airtable.com/appvFxwZc9yU8o8pK/Concepts?filter_project_id=${projectId}`
      }
    ]
  }
];

return [{ json: {
  project_id: projectId,
  slack_blocks: JSON.stringify(slackBlocks),
  slack_text: `PM approved ${concepts.length} concepts for ${brandName}. Ready for client review.`,
  client_email: clientEmail,
  client_name: clientName,
  brand_name: brandName,
  approved_count: concepts.length
} }];

// ============================================================
// PM Reject: Mark all concepts as needing revision
// ============================================================
const data = $input.first().json;
const concepts = data.concepts;
const notes = data.notes;

const items = concepts.map(c => ({ json: {
  record_id: c.id,
  pm_status: 'Revision',
  pm_notes: notes,
  overall_status: 'PM Review'
}}));

return items;

// ============================================================
// Client Approve: Determine which concepts client approved
// If concept_ids is empty, approve all PM-approved concepts
// ============================================================
const data = $input.first().json;
const concept_ids = data.concept_ids || [];
const notes = data.notes;
const concepts = data.concepts;

// Only consider concepts that PM already approved
const pmApproved = concepts.filter(c => {
  const status = c.pm_status || (c.fields && c.fields.pm_status);
  return status === 'Approved';
});

const approvedConcepts = concept_ids.length > 0
  ? pmApproved.filter(c => concept_ids.includes(c.id))
  : pmApproved;
const rejectedConcepts = concept_ids.length > 0
  ? pmApproved.filter(c => !concept_ids.includes(c.id))
  : [];

const items = [];

for (const c of approvedConcepts) {
  items.push({ json: {
    record_id: c.id,
    client_status: 'Approved',
    client_notes: notes || '',
    overall_status: 'Approved'
  }});
}

for (const c of rejectedConcepts) {
  items.push({ json: {
    record_id: c.id,
    client_status: 'Rejected',
    client_notes: notes || 'Not selected by client',
    overall_status: 'Client Review'
  }});
}

return items;

