  return status === 'Approved';
});
const approvedCount = concept_ids.length > 0
  ? pmApproved.filter(c => concept_ids.includes(c.id)).length
  : pmApproved.length;

return [{ json: {
  project_id: data.project_id,
  approved_count: approvedCount,
  brand_name: data.project.brand_name || data.project.fields?.brand_name || 'Brand'
} }];

